/* Independent navigation and media placeholders; original page CSS is retained above. */
html,body{margin:0;visibility:visible!important;opacity:1!important}
.hidden-during-prewarmup{visibility:visible!important}
wix-dropdown-menu{display:block;overflow:visible!important;visibility:visible!important}
wix-dropdown-menu nav>ul{display:flex!important;align-items:center;flex-wrap:nowrap}
wix-dropdown-menu nav>ul>li{display:block!important;position:relative!important;width:auto!important;min-width:0;overflow:visible!important;height:19px!important;visibility:visible!important}
wix-dropdown-menu nav>ul>li>div{cursor:pointer}
wix-dropdown-menu nav>ul>li>ul{display:none!important;position:absolute;top:100%;left:0;min-width:210px;background:white;box-shadow:0 6px 24px #0002;z-index:100001;padding:12px 0;list-style:none}
wix-dropdown-menu nav>ul>li:hover>ul,wix-dropdown-menu nav>ul>li:focus-within>ul,wix-dropdown-menu nav>ul>li[data-open]>ul{display:block!important}
wix-dropdown-menu nav>ul>li>ul a{display:block;padding:10px 18px;font:14px open-sans-v2,Arial,sans-serif;color:#0f4d6b;text-decoration:none}
wix-dropdown-menu nav>ul>li>ul a:hover{background:#edf3f5}
wix-dropdown-menu [id$="__more__"],wix-dropdown-menu [id$="dropWrapper"],wix-dropdown-menu .H4AHlN{display:none!important}
#SITE_HEADER{z-index:100000!important;overflow:visible!important}
wow-image,wix-image{display:block;background:#e5eaec}
wow-image img,wix-image img{object-fit:cover!important}
wix-video{display:block!important;background:#e5eaec!important}
video{display:none!important}
[data-motion-enter]{opacity:1!important;transform:none!important}
.export-notice{border:1px solid #cad5da;border-radius:8px;padding:12px;margin:8px;background:#f4f7f8;color:#0f4d6b;font:14px/1.5 Arial,sans-serif}
@media(max-width:1000px){body{min-width:1000px}}

wix-dropdown-menu nav>ul>li:nth-child(1){width:72px!important}
wix-dropdown-menu nav>ul>li:nth-child(2){width:99px!important}
wix-dropdown-menu nav>ul>li:nth-child(3){width:109px!important}
wix-dropdown-menu nav>ul>li:nth-child(4){width:108px!important}
wix-dropdown-menu nav>ul>li:nth-child(5){width:118px!important}
